package nhom10.phonenest.service;
import lombok.RequiredArgsConstructor; import nhom10.phonenest.dto.DoiTraDto; import nhom10.phonenest.entity.*; import nhom10.phonenest.enums.*; import nhom10.phonenest.exception.AppException; import nhom10.phonenest.repository.*; import nhom10.phonenest.util.IdGenerator; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.time.temporal.ChronoUnit; import java.util.*;
@Service @RequiredArgsConstructor @Transactional public class DoiTraService{private static final int HAN=7;private final YeuCauDoiTraRepository repo;private final DonHangRepository donRepo;private final ThongBaoService thongBao;private final NhatKyHoatDongService nhatKyHoatDongService;
 public DoiTraDto tao(String maKh,DoiTraDto.Request r){DonHang d=donRepo.findById(r.maDonHang()).filter(x->x.getKhachHang().getMaKh().equals(maKh)).orElseThrow(()->new AppException(HttpStatus.NOT_FOUND,"Không tìm thấy đơn hàng"));if(d.getTrangThai()!=TrangThaiDonHang.DA_GIAO)throw new AppException(HttpStatus.BAD_REQUEST,"Chỉ đơn đã giao mới được đổi trả");LocalDateTime moc=d.getNgayGiao()!=null?d.getNgayGiao():d.getNgayCapNhat();if(moc!=null&&ChronoUnit.DAYS.between(moc,LocalDateTime.now())>HAN)throw new AppException(HttpStatus.BAD_REQUEST,"Đã quá "+HAN+" ngày đổi trả");YeuCauDoiTra y=new YeuCauDoiTra();y.setMaYeuCau(IdGenerator.next("YC"));y.setDonHang(d);y.setLyDoChung(r.lyDo().trim());y.setNgayTao(LocalDateTime.now());y.setTrangThai(TrangThaiDoiTra.CHO_DUYET);for(ChiTietDonHang c:d.getChiTiet()){ChiTietDoiTra ct=new ChiTietDoiTra();ct.setMaChiTietDoiTra(IdGenerator.next("CTDT"));ct.setYeuCau(y);ct.setChiTietDonHang(c);ct.setSoLuong(c.getSoLuong());ct.setLoaiYeuCau(LoaiYeuCauDoiTra.TRA_HANG_HOAN_TIEN);ct.setLyDo(r.lyDo().trim());ct.setHinhAnhMinhChung(r.hinhAnhMinhChung());y.getChiTiet().add(ct);}repo.save(y);thongBao.guiQuanTri("Có yêu cầu đổi trả mới cho đơn "+d.getMaDonHang());return dto(y);}
 public List<DoiTraDto> cuaToi(String maKh){return donRepo.findByKhachHangMaKhOrderByNgayMuaDesc(maKh).stream().flatMap(d->repo.findByDonHangMaDonHangOrderByNgayTaoDesc(d.getMaDonHang()).stream()).map(this::dto).toList();} public List<DoiTraDto> tatCa(){return repo.findAll().stream().sorted(Comparator.comparing(YeuCauDoiTra::getNgayTao).reversed()).map(this::dto).toList();}
 public DoiTraDto capNhat(String ma,TrangThaiDoiTra moi){YeuCauDoiTra y=repo.findById(ma).orElseThrow(()->new AppException(HttpStatus.NOT_FOUND,"Không tìm thấy yêu cầu"));boolean ok=switch(y.getTrangThai()){case CHO_DUYET->moi==TrangThaiDoiTra.DA_DUYET||moi==TrangThaiDoiTra.TU_CHOI;case DA_DUYET->moi==TrangThaiDoiTra.DANG_XU_LY||moi==TrangThaiDoiTra.HOAN_TAT;case DANG_XU_LY->moi==TrangThaiDoiTra.HOAN_TAT;default->false;};if(!ok)throw new AppException(HttpStatus.BAD_REQUEST,"Không thể chuyển trạng thái này");Map<String,Object> duLieuTruoc=snapshot(y);y.setTrangThai(moi);thongBao.gui(y.getDonHang().getKhachHang().getMaKh(),"Yêu cầu đổi trả đơn "+y.getDonHang().getMaDonHang()+": "+moi.name());nhatKyHoatDongService.ghi(HanhDongAudit.CHANGE_RETURN_STATUS,LoaiDoiTuongAudit.RETURN,ma,duLieuTruoc,snapshot(y));return dto(y);}
 private Map<String,Object> snapshot(YeuCauDoiTra y){Map<String,Object> duLieu=new LinkedHashMap<>();duLieu.put("trangThai",y.getTrangThai()!=null?y.getTrangThai().name():null);return duLieu;}
 private DoiTraDto dto(YeuCauDoiTra y){String img=y.getChiTiet().stream().map(ChiTietDoiTra::getHinhAnhMinhChung).filter(Objects::nonNull).findFirst().orElse(null);return new DoiTraDto(y.getMaYeuCau(),y.getDonHang().getMaDonHang(),y.getDonHang().getKhachHang().getHoTen(),y.getLyDoChung(),img,y.getNgayTao().toLocalDate(),y.getTrangThai());}
}
